mapper.select:
SELECT e.id, e.eir_no, e.business_type, e.container_no, e.container_size, e.container_type, e.company_id, c.name AS companyName, e.tractor_id, t.plate_no AS plateNo, e.driver_id, d.name AS driverName, e.status, e.dispatch_time, e.gate_in_time, e.gate_out_time, e.audit_time, e.remark, e.create_time, a.appt_time AS apptTime, f.pay_status AS payStatus FROM eir_order e LEFT JOIN transport_company c ON c.id = e.company_id LEFT JOIN tractor t ON t.id = e.tractor_id LEFT JOIN driver d ON d.id = e.driver_id LEFT JOIN ( SELECT eir_id, MAX(create_time) AS appt_time FROM appointment GROUP BY eir_id ) a ON a.eir_id = e.id LEFT JOIN fee_record f ON f.eir_id = e.id
AND e.eir_no LIKE CONCAT('%', #{eirNo}, '%')
AND e.status = #{status}
AND e.business_type = #{businessType}
AND e.company_id = #{companyId}
AND e.driver_id = #{driverId}
ORDER BY e.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM eir_order e


